$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
function Binding {
 $ls=@(Get-CimInstance -Namespace 'root/StandardCimv2' -ClassName MSFT_NetTCPConnection -Filter '(LocalPort=8091 OR LocalPort=8095 OR LocalPort=8097 OR LocalPort=9600) AND State=2' -OperationTimeoutSec 3)
 if($ls.Count -gt 16){throw 'listener bound'}
 $rows=@(foreach($l in $ls){$proc=Get-CimInstance Win32_Process -Filter ('ProcessId='+[uint32]$l.OwningProcess) -Property ProcessId,CreationDate,ExecutablePath -OperationTimeoutSec 3; @{port=[int]$l.LocalPort;pid=[int]$proc.ProcessId;created=$proc.CreationDate.ToUniversalTime().ToString('o');exe=$proc.ExecutablePath}})
 ConvertTo-Json -InputObject $rows -Depth 4 -Compress
}
$before=Binding
$js=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
$manager=($js | & 'C:\Program Files\Enclave\runtime\node\node.exe' --input-type=module -)
$rc=$LASTEXITCODE
$after=Binding
[pscustomobject]@{before=($before|ConvertFrom-Json);nodeExit=$rc;manager=($manager|ConvertFrom-Json);after=($after|ConvertFrom-Json);readOnly=$true;admitted=$false}|ConvertTo-Json -Depth 12 -Compress
